<script lang="ts">
  import { onMount } from 'svelte'; import { Button } from 'm3-svelte';
  import { api, errorMessage, type Change, type Service, type Validation } from '$lib/api';
  let changes: Change[] = []; let services: Service[] = []; let loading = true; let loaded = false; let busy = false; let error = ''; let service = ''; let baseCommit = ''; let patch = '{}'; let selected: Change | undefined; let validation: Validation | undefined; let prUrl = ''; let refreshed = false;
  async function load() { loading = true; loaded = false; error = ''; try { const [c, s] = await Promise.all([api.changes(), api.services()]); changes = c.changes; services = s.services; loaded = true; } catch (e) { error = errorMessage(e); } finally { loading = false; } }
  async function create() { error = ''; let parsed: unknown; try { parsed = JSON.parse(patch); if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') throw new Error('Patch must be a JSON object.'); } catch (e) { error = errorMessage(e); return; } busy = true; try { selected = await api.createChange({ service, base_commit: baseCommit, patch: parsed as Record<string, unknown> }); validation = undefined; prUrl = ''; refreshed = false; loaded = false; changes = (await api.changes()).changes; loaded = true; } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  async function refreshChange() { if (!selected) return; busy = true; error = ''; validation = undefined; prUrl = ''; refreshed = false; try { const updated = await api.refreshChange(selected.id); selected = updated; changes = changes.map(change => change.id === updated.id ? updated : change); refreshed = true; } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  async function validate() { if (!selected) return; busy = true; error = ''; validation = undefined; prUrl = ''; try { validation = await api.validateChange(selected.id); } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  async function openPr() { if (!selected || !validation || validation.errors.length) return; busy = true; error = ''; try { const url = new URL((await api.openPr(selected.id)).url); if (!['https:', 'http:'].includes(url.protocol)) throw new Error('The server returned an invalid PR URL.'); prUrl = url.href; } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  onMount(load);
</script>
<div class="page"><div class="heading"><div><h1>Changes</h1><p class="subtitle">Propose a structured catalog patch, validate its renders, and open a review request.</p></div><Button variant="outlined" onclick={load}>Refresh</Button></div>
{#if error}<div class="error" role="alert">{error}</div>{/if}<section><h2>Recent changes</h2>{#if loading}<p role="status">Loading changes…</p>{:else if loaded && !changes.length}<p class="muted">No changes returned.</p>{:else if loaded}<div class="table-wrap"><table><thead><tr><th>Change</th><th>Service</th><th>Base commit</th><th>State</th><th>Action</th></tr></thead><tbody>{#each changes as change}<tr><td>{change.id}</td><td>{change.service}</td><td><code>{change.base_commit}</code></td><td>{change.state}</td><td><Button variant="text" disabled={busy} onclick={() => { selected = change; validation = undefined; prUrl = ''; refreshed = false; }}>Select</Button></td></tr>{/each}</tbody></table></div>{/if}</section>
<section class="section"><h2>Propose a change</h2><form class="panel form stack" onsubmit={(event) => { event.preventDefault(); create(); }}><label>Service<select required bind:value={service}><option value="" disabled>Select a service</option>{#each services as item}<option value={item.name}>{item.name}</option>{/each}</select></label><label>Base commit<input required bind:value={baseCommit} /></label><label>Structured patch (JSON object)<textarea required spellcheck="false" bind:value={patch}></textarea></label><p class="muted">Only catalog data is changed. Server-side schema and render validation remain authoritative.</p><div><Button type="submit" disabled={busy || loading}>Create proposal</Button></div></form></section>
{#if selected}<section class="section"><h2>Validate {selected.id}</h2><p class="muted">{selected.service} · base {selected.base_commit} · {selected.state}</p><div class="actions"><Button variant="outlined" onclick={refreshChange} disabled={busy}>Refresh proposal</Button><Button onclick={validate} disabled={busy}>Validate and render</Button>{#if validation && !validation.errors.length}<Button variant="outlined" onclick={openPr} disabled={busy}>Open pull request</Button>{/if}</div>{#if refreshed && !validation}<p role="status">Proposal refreshed. Validate and render again to review the regenerated preview before opening a pull request.</p>{/if}{#if validation}{#if validation.errors.length}<div class="error" role="alert"><strong>Validation failed</strong><ul>{#each validation.errors as issue}<li>{issue}</li>{/each}</ul></div>{:else}<p class="notice">Validation passed. Review both diffs before opening a pull request.</p>{/if}<h3>Data diff</h3><pre>{validation.data_diff || 'No data changes returned.'}</pre><h3>Rendered manifest diff</h3><pre>{validation.rendered_diff || 'No rendered changes returned.'}</pre>{/if}{#if prUrl}<p role="status">Pull request opened: <a href={prUrl} target="_blank" rel="noopener noreferrer">{prUrl}</a></p>{/if}</section>{/if}</div>
